test.courtconnect.assert_all_racket_spor.raw_code:
{{ config(severity='warn') }}
-- The platform should cover every racket sport on the sheet (expected: see var expected_racket_sports in dbt_project.yml).
-- Warns (does not fail) if the count differs, so a gap in the sheet is visible rather than silent.
select count(*) as sports_found, {{ var('expected_racket_sports') }} as sports_expected
from {{ ref('dim_sport') }}
where sport_family like 'Racket%'
having count(*) <> {{ var('expected_racket_sports') }}

test.courtconnect.assert_confidence_scor.raw_code:
-- The score must stay within 0-100.
select venue_id, confidence_score from {{ ref('mart_venue_confidence') }}
where confidence_score < 0 or confidence_score > 100

test.courtconnect.assert_courts_inside_r.raw_code:
-- Fails (returns rows) if a court has no region or falls outside its region's bounding box (a state in the regions var, ADR 0014, 0028):
-- catches bad geocodes and mis-scoped extractions.
select court_id, lat, lon, region
from {{ ref('dim_court') }}
where {{ outside_region_bbox('lat', 'lon', 'region') }}

test.courtconnect.assert_manual_venues_i.raw_code:
-- A hand-entered venue with a mistyped coordinate (swapped lat/lon, missing minus sign) or a missing/wrong region must fail the build.
select venue_key, lat, lon, region
from {{ ref('stg_manual_venues') }}
where {{ outside_region_bbox('lat', 'lon', 'region') }}

test.courtconnect.assert_net_height_sane.raw_code:
select sport_id, net_height_in
from {{ ref('dim_sport') }}
where net_height_in is not null and net_height_in not between 1 and 120

test.courtconnect.assert_venue_actions_f.raw_code:
{{ config(severity='warn') }}
-- Prices, dates and sign-up status on provider sites change. Warn when a CURRENT link-out has not been re-checked for 60 days.
select action_key, verified_on
from {{ ref('stg_venue_actions') }}
where (end_date is null or end_date >= current_date)
  and verified_on < current_date - 60

test.courtconnect.assert_watch_events_fr.raw_code:
{{ config(severity='warn') }}
-- Event details go stale (dates move, tickets sell out). Warn when an UPCOMING event has not been re-checked for 120 days.
select event_key, verified_on
from {{ ref('stg_watch_events') }}
where (end_date is null or end_date >= current_date)
  and verified_on < current_date - 120

test.courtconnect.assert_watch_events_va.raw_code:
-- Fails on a watch event that is internally inconsistent or unsafe to show:
--  * coordinates outside every covered state (typo)           * end before start
--  * a "confirmed" date with no dates              * links that are not https
select event_key, 'bad coordinates' as problem from {{ ref('stg_watch_events') }}
where {{ outside_all_region_bboxes('lat', 'lon') }}
union all
select event_key, 'end before start' from {{ ref('stg_watch_events') }}
where start_date is not null and end_date is not null and end_date < start_date
union all
select event_key, 'confirmed but missing dates' from {{ ref('stg_watch_events') }}
where date_status = 'confirmed' and (start_date is null or end_date is null)
union all
select event_key, 'link is not https' from {{ ref('stg_watch_events') }}
where (info_url is not null and info_url not like 'https://%') or (tickets_url is not null and tickets_url not like 'https://%')
union all
select event_key, 'no official link' from {{ ref('stg_watch_events') }}
where info_url is null and tickets_url is null
union all
select event_key, 'screening row missing ticket_info or source_note' from {{ ref('stg_watch_events') }}
where watch_format in ('watch_party', 'dome_screening', 'broadcast_only') and (ticket_info is null or source_note is null)

