            {% for column in timing_columns %}
                {{ column }} = regexp_replace({{ column }}, r'(\.\d{6})\d+', r'\1')
                {% if not loop.last %},{% endif %}
            {% endfor %}
            where {{ where_clause }}
        {% endset %}
        {% do elementary.run_query(update_query) %}
