        where {{ elementary.edr_timeadd(time_bucket.period, "(num + 1) * " ~ time_bucket.count, min_bucket_start_expr) }} <= {{ max_bucket_end_expr }}
    {%- endset %}
    {{ return(complete_buckets_cte) }}
