    {% for idx in extra_indexes %}
        {% if idx.columns is not defined %}
            {{
                exceptions.raise_compiler_error(
                    "elementary_extra_indexes entry for '"
                    ~ model_name
                    ~ "' is missing 'columns': "
                    ~ idx
