            }}
        {% endif %}
        {% set sorted_cols = idx.columns | sort | join(",") %}
        {% if sorted_cols not in seen_column_sets %}
            {% do seen_column_sets.append(sorted_cols) %}
            {% do merged_indexes.append(idx) %}
