        {% set direction_case_insensitive = anomaly_direction %}
        {% if direction_case_insensitive not in ["drop", "spike", "both"] %}
            {% do exceptions.raise_compiler_error(
                "Supported anomaly directions are: both, drop, spike. received anomaly_direction: {}".format(
                    anomaly_direction
                )
            ) %}
        {% endif %}
    {% else %}
        {% do exceptions.raise_compiler_error(
            "anomaly_direction can't be empty. Supported anomaly directions are: both, drop, spike"
        ) %}
    {% endif %}
{% endmacro %}

macro.elementary.get_days_back.macro_sql:
