macro.elementary.get_detection_delay.macro_sql:
{% macro get_detection_delay(detection_delay, model_graph_node) %}
    {%- set configured_detection_delay = elementary.get_test_argument(
        "detection_delay", detection_delay, model_graph_node
    ) %}
