        {%- elif resolved[col | lower] not in select_cols %}
            {%- do select_cols.append(resolved[col | lower]) %}
        {%- endif %}
    {%- endfor %}

    {%- if not select_cols %}
        {%- do return(
            default_clause
            if default_clause is not none
            else all_columns_clause
        ) %}
    {%- endif %}

    {%- do return(select_cols | join(", ")) %}
{% endmacro %}

